{"states": ["Initial State", "Mail Transaction in Progress"], "transitions": [
    {
      "from": "Initial State",
      "event": "EHLO or HELO",
      "action": "250 OK, clear state tables and buffers",
      "to": "Initial State"
    },
    {
      "from": "Initial State",
      "event": "MAIL",
      "action": "clear reverse-path, forward-path, and mail data buffers, insert reverse-path information",
      "to": "Mail Transaction in Progress"
    },
    {
      "from": "Mail Transaction in Progress",
      "event": "RCPT",
      "action": "append forward-path to forward-path buffer",
      "to": "Mail Transaction in Progress"
    },
    {
      "from": "Mail Transaction in Progress",
      "event": "DATA",
      "action": "append mail data to mail data buffer",
      "to": "Mail Transaction in Progress"
    },
    {
      "from": "Mail Transaction in Progress",
      "event": "RSET",
      "action": "discard stored sender, recipients, and mail data, clear buffers and state tables",
      "to": "Initial State"
    },
    {
      "from": "Mail Transaction in Progress",
      "event": "QUIT",
      "action": "send 221 OK reply, close transmission channel",
      "to": "Initial State"
    }
  ]
}

